import React, { useCallback, useEffect, useRef, useState } from 'react';
import classNames from 'classnames';
import { toast, Bounce } from 'react-toastify';
import { useTranslation } from '@getvim/translate';
import { Button, LabeledInput } from '../../atoms';
import { ShareUrlProps } from './types';
import './index.less';
import { messages } from './translations/messages';

function ShareUrl({
  name = 'textfield',
  label,
  url,
  buttonText = 'Copy link',
  className,
  onClick,
}: ShareUrlProps) {
  const intl = useTranslation({});
  const inputRef = useRef<HTMLInputElement>(null);
  const [text, setText] = useState<string>(url);

  useEffect(() => {
    setText(url);
  }, [url]);

  const createSuccess = useCallback((successMessage: string) => {
    toast.dismiss(successMessage);
    toast.clearWaitingQueue();

    toast.info(<div>{successMessage}</div>, {
      transition: Bounce,
      closeButton: false,
      autoClose: 1500,
      toastId: `${successMessage}`,
      bodyClassName: 'share-url-toast',
    });
  }, []);

  const copyText = useCallback(() => {
    if (inputRef != null && inputRef.current != null) {
      if (onClick) {
        onClick();
      }
      createSuccess(intl.formatMessage(messages.copied));
      inputRef.current.select();
      document.execCommand('copy');
    }
  }, [createSuccess, intl, onClick]);

  return (
    <div className="share-url">
      <form className="share-url-form">
        <div className="share-url-icon">
          <i className="icon-chain-link i-va-fix-2 text-theme-primary" />
        </div>
        <LabeledInput
          id={name}
          className={classNames(className, 'share-url-input')}
          refs={inputRef}
          htmlFor={name}
          label={label}
          onChange={(e) => {
            setText(e.target.value);
          }}
          value={text}
          type="text"
        />

        <Button
          buttonType="small"
          className="share-url-button"
          onClick={copyText}
          text={buttonText}
        />
      </form>
    </div>
  );
}

export default ShareUrl;
